    perf:"2 минуты. Каждый риск заканчивается решением, а не оценкой.",
    qs:[
      {id:"pm3_1",kind:"num",t:"Риск с вероятностью 20% и влиянием $500k. Какова ожидаемая потеря?",a:100000,unit:"$",sol:["0,2 × 500 000.","Ожидаемая потеря 100 000."],trap:"Ошибка — назвать 500 000 как ущерб. Вероятность обязательно применяется к влиянию."},
      {id:"pm3_2",kind:"num",t:"Три риска: 30% × $200k, 10% × $900k, 60% × $100k. Каков наибольший ожидаемый ущерб?",a:90000,unit:"$",sol:["0,3 × 200 = 60 тыс.","0,1 × 900 = 90 тыс.","0,6 × 100 = 60 тыс.","Наибольший — 90 тыс."],trap:"Ошибка — выбрать риск с наибольшим влиянием или с наибольшей вероятностью. Оба крайних варианта дают по 60 тыс."},
      {id:"pm3_3",kind:"num",t:"Мера стоимостью $30k снижает ожидаемую потерю со $100k до $20k. Какова чистая выгода меры?",a:50000,unit:"$",sol:["Экономия: 100 000 − 20 000 = 80 000.","Минус стоимость: 80 000 − 30 000 = 50 000."],trap:"Ошибка — сравнить стоимость меры с полной потерей 100k и забыть, что после меры часть риска остаётся."},
      {id:"pm3_4",kind:"num",t:"Мера стоимостью $80k снижает ожидаемую потерю со $100k до $20k. Какова чистая выгода меры?",a:0,tol:0.01,unit:"$",sol:["Экономия 80 000 равна стоимости 80 000.","Чистая выгода нулевая."],trap:"Ошибка — купить меру при нулевой выгоде. Ты получаешь дополнительную сложность и процесс, не меняя ожидаемый результат."},
      {id:"pm3_5",kind:"num",t:"Ожидаемые потери по портфелю: $100k, $60k и $40k. Какой запас на риски заложить, если закладывать полную сумму ожидаемых потерь?",a:200000,unit:"$",sol:["100 + 60 + 40 = 200 тыс."],trap:"Ошибка — закладывать худший случай по каждому риску одновременно. Так запас раздувается и проекты не стартуют."},
      {id:"pm3_6",kind:"num",t:"Три категории инцидентов дают 70% случаев. Следующая по частоте категория добавляет ещё 12%. Сколько категорий закрыть, чтобы покрыть 80%?",a:4,unit:"категории",sol:["После трёх категорий накоплено 70%.","Четвёртая добавляет 12%, итого 82%.","Нужно четыре."],trap:"Ошибка — остановиться на трёх и не проверить, добирает ли следующая до порога."},
      {id:"pm3_7",kind:"num",t:"20 клиентов из 100 дают 80% выручки. Какую долю выручки дают остальные 80 клиентов?",a:20,unit:"%",sol:["Вся выручка это 100%.","Остаток: 100 − 80 = 20%."],trap:"Ошибка — считать, что остальные дают 80%, поменяв группы местами. Малое число клиентов даёт большую часть денег."},
      {id:"pm3_8",kind:"num",t:"Ожидаемая потеря по риску $150k. Страховка стоит $60k и покрывает ущерб полностью. Какова чистая выгода страховки?",a:90000,unit:"$",sol:["Ожидаемая потеря 150 000 против премии 60 000.","Выгода 90 000."],trap:"Ошибка — сравнивать премию с полным ущербом, а не с ожидаемой потерей. Иначе любая страховка выглядит выгодной."},
      {id:"pm3_9",kind:"mc",t:"Какой риск нельзя осознанно принять и оставить как есть?",opts:["Потеря лицензии, без которой деятельность невозможна","Задержка внутреннего отчёта на неделю","Рост стоимости подрядчика на 5%","Два проекта используют одного эксперта"],correct:0,sol:["Принимать можно только риск с ограниченным и обратимым влиянием.","Риск, который останавливает деятельность или нарушает обязательство, снижают или переносят — его не принимают.","Остальные варианты это операционные неудобства с ограниченной ценой."],trap:"Ошибка — ранжировать по вероятности. Даже маловероятный риск с катастрофическим влиянием не принимают."}
    ]
